import {Tournament,drawEntrants,ROUND_NAMES} from './engine/tournament.js';
export class TournamentUI{
 constructor(h){this.h=h;this.$=h.$;this.model=null;this.phase='setup';this.paused=false;this.age=0;this.generation=0;this.drawCount=0;const $=this.$;
  for(let i=0;i<8;i++){const count=$('cupCount'+i);count.value='1';for(let j=0;j<5;j++){const pick=$('cupPick'+i+'_'+j);pick.innerHTML=Object.entries(h.names).map(([id,name])=>'<option value="'+id+'">'+name+'</option>').join('');pick.value=Object.keys(h.names)[(i+j)%Object.keys(h.names).length];pick.onchange=()=>this.update();}count.onchange=()=>{this.showSlots();this.update();};$('cupName'+i).oninput=()=>this.update();$('cupName'+i).value='Entrant '+(i+1);}
  $('cupAuto').checked=true;$('cupFormat').value='single';$('cupFormat').onchange=()=>this.showSlots();$('cupDraw').onclick=()=>this.draw();$('cupCreate').onclick=()=>this.create();$('cupNext').onclick=()=>this.next();$('cupPause').onclick=()=>this.toggle();$('cupBack').onclick=()=>{this.leave();h.reset();};$('cupAuto').onchange=()=>this.age=0;this.showSlots();this.update();
 }
 isMode(){return this.$('mode').value==='tournament';}
 get active(){return this.isMode()&&!!this.model;}
 battleConfig(){return this.active?this.model.battleConfig():null;}
 showSlots(){const teams=this.$('cupFormat').value==='teams';for(let i=0;i<8;i++){this.$('cupCount'+i).hidden=!teams;for(let j=0;j<5;j++)this.$('cupPick'+i+'_'+j).hidden=j>=(teams?Number(this.$('cupCount'+i).value):1);}}
 read(){return Array.from({length:8},(_,i)=>({name:this.$('cupName'+i).value||'Entrant '+(i+1),players:Array.from({length:this.$('cupFormat').value==='teams'?Number(this.$('cupCount'+i).value):1},(_,j)=>this.$('cupPick'+i+'_'+j).value)}));}
 draw(){const entries=drawEntrants(this.read(),this.h.settings().seed+'-DRAW-'+ ++this.drawCount);entries.forEach((e,i)=>{this.$('cupName'+i).value=e.name;this.$('cupCount'+i).value=String(e.players.length);e.players.forEach((id,j)=>this.$('cupPick'+i+'_'+j).value=id);});this.showSlots();this.update();this.$('cupNotice').textContent='Đã bốc thăm. Các ô 1–2, 3–4, 5–6, 7–8 là bốn cặp tứ kết.';}
 create(){if(!this.isMode())return;try{this.model=new Tournament(this.read(),{...this.h.settings(),format:this.$('cupFormat').value});this.phase='ready';this.paused=false;this.update();return this.next();}catch(e){this.$('cupNotice').textContent=e.message;}}
 async next(){if(!this.active||this.model.champion!==null||['loading','intro','battle'].includes(this.phase))return;const token=++this.generation;this.phase='loading';this.age=0;this.paused=false;this.update();await this.h.reset();if(token!==this.generation||!this.active)return;if(!this.h.ready()){this.phase='ready';this.$('cupNotice').textContent='Không tải được tài nguyên. Nhấn Trận tiếp theo để thử lại.';this.update();return;}this.phase='intro';this.age=0;this.showIntro();this.update();}
 overlay(tag,title,line){const box=this.$('overlay');box.style.display='flex';box.classList.add('cup-overlay');box.classList.remove('result');box.innerHTML='';for(const [kind,text] of [['span',tag],['h2',title],['p',line]]){const el=document.createElement(kind);el.textContent=text;box.append(el);}
 if(tag==='CHAMPION'){const trophy=document.createElement('div');trophy.className='cup-trophy';trophy.innerHTML='<svg viewBox="0 0 100 90" aria-label="Champion trophy"><path d="M25 8H75L66 48L55 58V72H73V82H27V72H45V58L34 48Z" fill="#ffd76d" stroke="#fff2be" stroke-width="2"/><path d="M25 15H12Q8 45 34 47M75 15H88Q92 45 66 47" fill="none" stroke="#ffd76d" stroke-width="5"/></svg>';box.append(trophy);}
 if(tag==='WINNER'||tag==='CHAMPION'){const mini=document.createElement('div');mini.className='cup-mini';for(let r=0;r<3;r++){const col=document.createElement('div');const title=document.createElement('b');title.textContent=ROUND_NAMES[r];col.append(title);for(const m of this.model.matches.filter(m=>m.round===r)){const cell=document.createElement('span');cell.textContent=m.winner!==null?this.model.entries[m.winner].name:m.entrants.map(id=>id===null?'TBD':this.model.entries[id].name).join(' / ');cell.className=m.winner!==null?'resolved':'';col.append(cell);}mini.append(col);}box.append(mini);}
 }
 showIntro(){const m=this.model.current,[a,b]=m.entrants.map(id=>this.model.entries[id]);this.overlay(ROUND_NAMES[m.round]+' / MATCH '+(m.index+1)+' OF 7',a.name+'  VS  '+b.name,a.players.map(id=>this.h.names[id]).join(' + ')+'  /  '+b.players.map(id=>this.h.names[id]).join(' + '));}
 toggle(){if(!this.isMode())return;if(!this.model)return this.create();if(this.phase==='complete')return;this.paused=!this.paused;if(this.phase==='battle'&&!this.h.duel().result)this.h.toggleBattle();this.update();}
 frame(dt){if(!this.active||this.paused)return;this.age+=dt;
  if(this.phase==='intro'&&this.age>=1.6){this.phase='battle';this.age=0;this.$('overlay').style.display='none';this.h.toggleBattle();this.update();}
  if(this.phase==='battle'&&this.h.duel().result&&this.h.resultAge()>2.3){const d=this.h.duel(),m=this.model.current,round=m.round;const won=this.model.record(d.result,d.fighters);this.phase=this.model.champion!==null?'complete':'waiting';this.age=0;
   if(!won)this.overlay('DRAW','REMATCH','The same bracket match will be replayed.');else{const e=this.model.entries[m.winner];this.overlay(this.phase==='complete'?'CHAMPION':'WINNER',e.name,e.players.map(id=>this.h.names[id]).join(' + ')+' / '+e.damage.toFixed(0)+' DAMAGE / '+e.kos+' KOs');}
   this.update();
  }
  if(this.phase==='waiting'&&this.$('cupAuto').checked&&this.age>=2.5)this.next();
 }
 leave(){this.generation++;this.model=null;this.phase='setup';this.paused=false;this.age=0;this.h.stop();this.$('overlay').classList.remove('cup-overlay');this.update();}
 update(){const $=this.$,active=this.active;$('tournamentPanel').hidden=!this.isMode();$('cupSetup').hidden=active;$('cupNext').disabled=!active||!['ready','waiting'].includes(this.phase);$('cupPause').disabled=!active||this.phase==='complete';$('cupPause').textContent=this.paused?'Tiếp tục':'Tạm dừng';$('cupBack').hidden=!active;if(active){$('start').disabled=this.phase==='complete'||this.phase==='loading';$('start').textContent=this.phase==='waiting'?'Trận tiếp theo':this.paused?'Tiếp tục':'Tạm dừng';}
  for(const id of ['reset','swap','seed','applyStats','defaultStats','applyArenaScale','applyGlobalHp','resetGlobalHp','quickHp10','teamUltimateToggleMatch','teamUltimateToggleTeam'])$(id).disabled=active;
  const board=$('cupBracket');board.innerHTML='';const entries=this.model?.entries||this.read();
  for(let round=0;round<3;round++){const column=document.createElement('div');column.className='cup-round';const heading=document.createElement('h3');heading.textContent=ROUND_NAMES[round];column.append(heading);const matches=this.model?this.model.matches.filter(m=>m.round===round):Array.from({length:round===0?4:round===1?2:1},(_,i)=>({index:round===0?i:round===1?4+i:6,entrants:round===0?[i*2,i*2+1]:[null,null],winner:null}));
   for(const m of matches){const card=document.createElement('div');card.className='cup-match'+(this.model?.current===m?' current':'');const label=document.createElement('small');label.textContent='MATCH '+(m.index+1);card.append(label);for(const id of m.entrants){const row=document.createElement('div');row.className='cup-entrant'+(id!==null&&id===m.winner?' won':'');if(id===null)row.textContent='TBD';else{const e=entries[id],img=document.createElement('img');img.src=this.h.portraitURL(e.players[0]);img.alt='';row.append(img);const name=document.createElement('span');name.textContent=e.name;row.append(name);}card.append(row);}column.append(card);}board.append(column);}
  const stats=$('cupStandings');stats.innerHTML='';stats.hidden=!active;if(active){for(const e of [...this.model.entries].sort((a,b)=>b.wins-a.wins||b.damage-a.damage)){const row=document.createElement('div');row.textContent=e.name+' / '+e.wins+' WINS / '+e.damage.toFixed(0)+' DAMAGE / '+e.kos+' KOs';stats.append(row);}}
  if(this.model?.champion!==null&&this.model?.champion!==undefined){const e=this.model.entries[this.model.champion];$('cupNotice').textContent='CHAMPION — '+e.name+' / '+e.wins+' WINS / '+e.damage.toFixed(0)+' DAMAGE / '+e.kos+' KOs';}else if(active)$('cupNotice').textContent='Trận '+((this.model.current?.index??6)+1)+'/7 · '+(this.paused?'Tạm dừng':this.phase==='waiting'?'Chờ trận tiếp theo':this.phase==='loading'?'Đang tải tài nguyên':'Giải đấu đang diễn ra');
 }
 draw(ctx,clock){if(!this.active)return;const m=this.model.current;ctx.save();ctx.textAlign='center';ctx.font='bold 14px Segoe UI';ctx.fillStyle='#ffe2a3';ctx.fillText(this.phase==='complete'?'DOWN ARENA CHAMPIONSHIP':(m?ROUND_NAMES[m.round]:'TOURNAMENT')+' / SINGLE ELIMINATION',480,25);
  if(this.phase==='complete'){ctx.globalCompositeOperation='lighter';for(let i=0;i<36;i++){const x=(i*137+clock*15)%960,y=(i*61+clock*(12+i%5))%540;ctx.fillStyle=i%2?'#ffd76d':'#7adfff';ctx.fillRect(x,y,3,6);}ctx.globalCompositeOperation='source-over';ctx.fillStyle='#ffd76d';ctx.beginPath();ctx.moveTo(445,85);ctx.lineTo(515,85);ctx.lineTo(503,125);ctx.lineTo(486,137);ctx.lineTo(486,151);ctx.lineTo(508,151);ctx.lineTo(508,160);ctx.lineTo(452,160);ctx.lineTo(452,151);ctx.lineTo(474,151);ctx.lineTo(474,137);ctx.lineTo(457,125);ctx.closePath();ctx.fill();ctx.strokeStyle='#fff0b5';ctx.lineWidth=4;ctx.beginPath();ctx.arc(446,102,17,Math.PI/2,Math.PI*1.5);ctx.stroke();ctx.beginPath();ctx.arc(514,102,17,-Math.PI/2,Math.PI/2);ctx.stroke();}ctx.restore();}
}
